  static void Wait(Task task){if(task!=null)NavigationTests.Wait(task);}
  static T Open<T>(T w) where T:Window {w.Left=-18000;w.Top=-18000;w.ShowActivated=false;w.ShowInTaskbar=false;w.WindowStartupLocation=WindowStartupLocation.Manual;windows.Add(w);w.Show();Wait(Task.Delay(100));w.UpdateLayout();return w;}
  static void Close(Window w){w.Close();windows.Remove(w);}
  static IEnumerable<DependencyObject> Nodes(DependencyObject root){var seen=new HashSet<DependencyObject>();var todo=new Stack<DependencyObject>();todo.Push(root);while(todo.Count>0){var n=todo.Pop();if(!seen.Add(n))continue;yield return n;if(n is Visual)for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)todo.Push(VisualTreeHelper.GetChild(n,i));foreach(object c in LogicalTreeHelper.GetChildren(n)){var d=c as DependencyObject;if(d!=null)todo.Push(d);}}}
  static string Safe(string text){if(text==null)return null;return text.Replace(data,@"C:\Examples").Replace(output,@"C:\Examples").Replace("synthetic-demo-data","Examples").Replace(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),@"C:\Users\Demo");}
  static void Shot(Window w,string id){Wait(Task.Delay(180));w.UpdateLayout();foreach(var panel in Nodes(w).OfType<FilePanel>())panel.WebDemoChrome(code=="cs");foreach(var node in Nodes(w).ToArray()){var pathLabel=node as PathTextBlock;if(pathLabel!=null)pathLabel.FullPath=Safe(pathLabel.FullPath);var text=node as TextBlock;if(text!=null&&text.Text!=null){string safe=Safe(text.Text);if(safe!=text.Text)text.Text=safe;}var box=node as TextBox;if(box!=null&&box.Text!=null){string safe=Safe(box.Text);if(safe!=box.Text)box.Text=safe;}}
   w.UpdateLayout();var visible=Nodes(w).OfType<TextBlock>().Where(x=>x.IsVisible).Select(x=>x.Text).Concat(Nodes(w).OfType<TextBox>().Where(x=>x.IsVisible).Select(x=>x.Text)).ToArray();string all=String.Join("\n",visible);if(all.Contains(data)||all.Contains("Programování")||all.Contains("janra"))throw new Exception("Unsanitized local path in "+id+": "+all);File.WriteAllLines(Path.Combine(output,code+"-"+id+".visible-text.txt"),visible);var content=(FrameworkElement)w.Content;int width=(int)Math.Ceiling(content.ActualWidth),height=(int)Math.Ceiling(content.ActualHeight);if(width<250||height<100)throw new Exception("Empty screenshot: "+id);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen()){dc.DrawRectangle(CompactTheme.Chrome,null,new Rect(0,0,width,height));dc.DrawRectangle(new VisualBrush(content),null,new Rect(0,0,width,height));}var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(drawing);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));string path=Path.Combine(output,code+"-"+id+".png");using(var file=File.Create(path))encoder.Save(file);shots.Add(path);File.WriteAllLines(Path.Combine(output,"progress.txt"),shots);}
