  static void Picture(string path,int variant){var v=new DrawingVisual();using(var d=v.RenderOpen()){d.DrawRectangle(new LinearGradientBrush(Color.FromRgb((byte)(117+variant*16),(byte)(193-variant*8),(byte)(231-variant*5)),Color.FromRgb(229,242,242),90),null,new Rect(0,0,800,500));d.DrawEllipse(Brushes.LightGoldenrodYellow,null,new Point(620-variant*70,90+variant*12),45,45);d.DrawGeometry(new SolidColorBrush(Color.FromRgb(83,127,148)),null,Geometry.Parse("M0,370 L210,120 L360,310 L490,150 L800,390 Z"));d.DrawGeometry(new SolidColorBrush(Color.FromRgb(231,240,242)),null,Geometry.Parse("M140,205 L210,120 L275,205 L240,190 L210,215 L183,190 Z M445,205 L490,150 L535,205 L510,194 L493,211 L475,195 Z"));d.DrawRectangle(new LinearGradientBrush(Color.FromRgb(86,151,155),Color.FromRgb(38,104,126),90),null,new Rect(0,355,800,145));d.DrawGeometry(new SolidColorBrush(Color.FromRgb(80,136,92)),null,Geometry.Parse("M0,390 Q180,340 330,500 L0,500 Z"));d.DrawGeometry(new SolidColorBrush(Color.FromRgb(54,115,79)),null,Geometry.Parse("M800,350 Q570,375 500,500 L800,500 Z"));}var b=new RenderTargetBitmap(800,500,96,96,PixelFormats.Pbgra32);b.Render(v);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(b));using(var stream=File.Create(path))enc.Save(stream);}
  static void Fixtures(){foreach(string folder in new[]{"Documents","Backup","Pictures","Music","Projects","Archive"})Directory.CreateDirectory(Path.Combine(data,folder));File.WriteAllText(Path.Combine(data,"Documents","Readme.txt"),"File Compass demonstration\r\n\r\nAll names, files and content in this gallery are fictional.\r\nNo personal files or connections are used.\r\n");File.WriteAllText(Path.Combine(data,"Documents","Inventory.csv"),"Product;Quantity;Price\r\nUSB adapter;12;19.90\r\nNotebook stand;8;34.50\r\nUSB-C cable;24;9.90\r\nDesk light;6;29.00\r\n",new UTF8Encoding(true));File.WriteAllText(Path.Combine(data,"Documents","Settings.json"),"{\r\n  \"application\": \"File Compass Demo\",\r\n  \"version\": 1,\r\n  \"backup\": {\r\n    \"enabled\": true,\r\n    \"folders\": [\"Documents\", \"Pictures\", \"Projects\"]\r\n  }\r\n}\r\n");File.WriteAllText(Path.Combine(data,"Documents","Project-notes.md"),"# Weekend project\r\n\r\n- Review the draft\r\n- Export the pictures\r\n- Create a backup\r\n");File.Copy(Path.Combine(data,"Documents","Readme.txt"),Path.Combine(data,"Backup","Readme.txt"),true);
   for(int i=0;i<4;i++)Picture(Path.Combine(data,"Pictures",new[]{"Mountain-lake","Alpine-trail","Summer-valley","Morning-light"}[i]+".png"),i);
   using(var w=new BinaryWriter(File.Create(Path.Combine(data,"Music","Demo-Artist-Sample.wav")))){int bytes=96000;w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write(36+bytes);w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(48000);w.Write(96000);w.Write((short)2);w.Write((short)16);w.Write(Encoding.ASCII.GetBytes("data"));w.Write(bytes);for(int i=0;i<48000;i++)w.Write((short)(Math.Sin(i*.06)*600));}
   foreach(var item in new[]{Tuple.Create("Projects/Design-assets.bin",2400000),Tuple.Create("Archive/Previous-backup.bin",6200000)})using(var f=File.Create(Path.Combine(data,item.Item1)))f.SetLength(item.Item2);
